INSERT INTO public.listing_sources (listing_id, source_type, publisher_name, source_url, reference_code, captured_at, notes) VALUES (property_listing_id, 'editorial_import', 'บริษัท บริหารสินทรัพย์สุขุมวิท จำกัด (SAM)', 'https://www.sam.or.th/site/npa/detail.php?id=23189&keyref=6007684', 'SL0148', now(), 'Official source captured 2026-09-11. THB 6,721,000; 44 sq.wah; two three-storey units, four bedrooms/six bathrooms. Separate stairs, connected ground floors only. Proposed road alignment ฌ14 and source enquiry reporting no expropriation project both disclosed with current verification required. Nineteen source photos, dates 2025-01-20 and 2026-05-13. Navigation/map agree. All-status duplicate search no matches.') ;
